@RestController
@RequestMapping("/api/v1/shipping-addresses")
public class ShippingAddressController {

    @GetMapping
    public Flux<ShippingAddress> getAllAddresses(@RequestParam(required = false) UUID userId) {
        // Returns a collection of pluralized resources using reactive WebFlux
        return shippingAddressService.findAllByUserId(userId);
    }

    @GetMapping("/{addressId}")
    public Mono<ShippingAddress> getAddressById(@PathVariable UUID addressId) {
        // Targets a singular instance within the resource collection
        return shippingAddressService.findById(addressId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public Mono<ShippingAddress> createAddress(@RequestBody Mono<ShippingAddressDto> dto) {
        // Uses noun-based plural endpoint with POST method for resource creation
        return shippingAddressService.create(dto);
    }
}
